{"command": "cd /workspace/build && cat > diffhead.py <<'EOF'
import struct,sys,json,subprocess
def head(path):
    d=open(path,'rb').read()
    return d[0x3C:0x50].hex(), len(d)
for ch in (2,4,8,16,32):
    subprocess.run(['ft2','call','module_new',json.dumps({'channels':ch,'name':'H%d'%ch})],capture_output=True)
    subprocess.run(['ft2','call','module_save',json.dumps({'path':'/workspace/build/h%d.xm'%ch,'format':'xm'})],capture_output=True)
    print(ch, head('/workspace/build/h%d.xm'%ch))
EOF
python3 diffhead.py"}

