{"command": "cd /workspace/build && cat > composer.py <<'PYEOF'
"""Keygen tune builder for FT2-clone MCP session."""
import json, os, sys
sys.path.insert(0,'/workspace/build')
from util import call, mkwav, loadwav

# ---------------- music helpers ----------------
def N(midi): return midi + 8          # on-disk note number (root law: freq = 440*2^((N-77)/12))
ROOT = 53                            # N whose playback = 110 Hz (sample fundamental)
BPM, SPEED = 137, 2
ROWS = 16                            # rows per bar; 4 subdivisions of 4 rows

CHORDS = {    # name -> (bass MIDI, [pitch classes above bass root, triad/7th tones as MIDI-12 multiples])
 'F' : (41, [0,4,7,12]),
 'G' : (43, [0,4,7,12]),
 'Am': (45, [0,3,7,12]),
 'Em': (40, [0,3,7,12]),
 'C' : (48, [0,4,7,12]),
 'Dm': (50, [0,3,7,12]),
 'E' : (40, [0,4,7,12]),
}
def chord_notes(name, octave=1):
    """mid-range chord tones (MIDI) for pads/leads"""
    root, ivs = CHORDS[name]
    return [root + i + 12*octave for i in ivs]

PROG_MAIN = ['F','G','Am','Em','F','C','Dm','E']
PROG_B    = ['Am','Em','F','C','Dm','Am','E','E']

# ---------------- instrument bank ----------------
INSTS = [   # (idx, name, sample, sample_vol, pan)
 (1,'LEAD','lead',64,128),
 (2,'BASS','bass',64,128),
 (3,'SUBBASS','sub',56,128),
 (4,'PAD','pad',46,128),
 (5,'ORGAN','organ',50,128),
 (6,'PLOCK','plock',54,128),
 (7,'PLUCK','pluck',52,128),
 (8,'BELL','bell',46,128),
 (9,'KICK','kick',64,128),
 (10,'SNARE','snare',56,128),
 (11,'HAT','hat',44,128),
 (12,'CHAT','chat',46,128),
 (13,'CLAP','clap',52,128),
 (14,'TOM','tom',56,128),
 (15,'TOMHI','tomhi',52,128),
 (16,'CRASH','crash',48,128),
 (17,'RISER','riser',46,128),
 (18,'STRINGS','organ',44,128),
]
# channel map
KICK,SNR,HAT,BASS,SUB,LD,LD2,PLC,PLC2,ORG,PD1,PD2,ARP,FX,TOM,TOMH = range(16)
PANCH = {KICK:128,SNR:128,HAT:96,BASS:128,SUB:128,LD:136,LD2:96,PLC:72,PLC2:184,
         ORG:152,PD1:84,PD2:172,ARP:116,FX:128,TOM:104,TOMH:176}
INSTCH = {KICK:9,SNR:10,HAT:11,BASS:2,SUB:3,LD:1,LD2:1,PLC:6,PLC2:6,ORG:5,
          PD1:4,PD2:4,ARP:8,FX:17,TOM:14,TOMH:15}

def new_pattern(rows=ROWS):
    return {'rows':rows, 'cells':{}}

def put(pat, row, ch, note=None, ins=None, vol=None, fx=None, fxp=None):
    key = (row, ch)
    c = pat['cells'].setdefault(key, {})
    if note is not None: c['note'] = note
    if ins is not None: c['ins'] = ins
    if vol is not None: c['vol'] = vol
    if fx is not None: c['fxt'] = fx
    if fxp is not None: c['fxp'] = fxp

def keyoff(pat, row, ch):
    put(pat, row, ch, note=97)

# ---------------- part writers ----------------
def bass_seq(pat, chord, style, start_row=0, vol=60):
    """style: 'drive' 8ths, 'pump' 16ths, 'long' halves"""
    root = N(CHORDS[chord][0])
    fifth = N(CHORDS[chord][0]+7)
    octv = N(CHORDS[chord][0]+12)
    rows = []
    if style == 'drive':
        for s in range(4):
            rows.append([(root if s % 2 == 0 else fifth, 0), (octv if s in (1,3) else root, 2)])
    seq = []
    if style == 'drive':
        for r in range(ROWS):
            if r % 4 == 0: seq.append(root)
            elif r % 4 == 2: seq.append(octv if (r//4) % 2 else fifth)
    elif style == 'pump':
        for r in range(ROWS):
            if r % 2 == 0: seq.append(root)
            elif r % 8 == 7: seq.append(octv)
    elif style == 'long':
        seq = None
        put(pat, 0+start_row, BASS, note=root, ins=2, vol=vol)
        put(pat, 8+start_row, BASS, note=fifth, ins=2, vol=vol-6)
        return
    elif style == 'gallop':
        for r in range(ROWS):
            m = r % 8
            if m in (0,2,4,6): seq.append(root)
            elif m == 5: seq.append(octv)
    elif style == 'walk':
        pats = [root, root, fifth, octv, root, root, N(CHORDS[chord][0]+int(12*1.0)), fifth]
        for r in range(ROWS):
            if r % 2 == 0: seq.append(pats[(r//2) % 8])
    for i, nte in enumerate(seq):
        v = vol if i % 4 == 0 else vol-8
        put(pat, i+start_row, BASS, note=nte, ins=2, vol=max(20,v))

def sub_seq(pat, chord, on_rows=(0,8), vol=44):
    root = N(CHORDS[chord][0])
    for r in on_rows:
        put(pat, r, SUB, note=root-12, ins=3, vol=vol)
        keyoff(pat, r+6, SUB)

def pad_chord(pat, chord, octs=(1,), vols=(40,), long=True):
    ns = []
    for o, v in zip(octs, vols):
        ns += [(m, v) for m in chord_notes(chord, o)]
    for i,(m,v) in enumerate(ns):
        ch = PD1 if i < len(ns)//2 else PD2
        put(pat, 0, ch, note=N(m), ins=4, vol=v)
    if not long:
        for i,(m,v) in enumerate(ns):
            ch = PD1 if i < len(ns)//2 else PD2
            keyoff(pat, 12, ch)

def arp_fig(pat, chord, style='16', vol=42, ch=ARP, octs=(2,)):
    tones = chord_notes(chord, 2)
    seq = {
      '16':  [0,1,2,3,2,1,3,2,0,1,2,3,3,2,1,0],
      'up':  [0,1,2,3,3,2,1,0],
      'oc':  [0,2,1,3,2,3,1,2],
      'brk': [0,3,1,2,3,0,2,1],
    }[style]
    for r in range(ROWS):
        if style == '16':
            i = r
        else:
            if r % 2: continue
            i = (r//2) % len(seq)
        m = tones[seq[i] % len(tones)]
        v = vol if r % 4 == 0 else vol - 8
        put(pat, r, ch, note=N(m), ins=8, vol=max(16, v))
        if r % 4 == 3: keyoff(pat, r, ch) if False else None

def plock_seq(pat, chord, style, vol=40, ch=PLC):
    tones = chord_notes(chord, 1)
    steps = {
      'a': [(0,0),(2,4),(4,8),(6,12),(8,7),(11,10),(13,12),(15,3)],
      'b': [(0,0),(3,2),(6,4),(9,7),(12,11),(14,12)],
      'c': [(0,0),(2,3),(4,7),(6,10),(8,12),(10,7),(12,3),(14,0)],
      'd': [(0,12),(4,7),(8,0),(12,4)],
    }[style]
    for r, deg in steps:
        m = tones[deg % len(tones)] + (12*(deg//len(tones)))
        put(pat, r, ch, note=N(m), ins=6, vol=vol)

def organ_stab(pat, chord, rows=(6,14), vol=40, ch=ORG):
    tones = chord_notes(chord, 1)
    for r in rows:
        for k,m in enumerate(tones[:3]):
            put(pat, r, ch if k == 0 else ORG, note=N(m), ins=5, vol=vol-k*4)
        keyoff(pat, r+3, ch)

def melody_seq(pat, seq, ch=LD, vol=62, ins=1, transpose=0):
    """seq: list of (midi or None, duration in subdivisions)"""
    row = 0
    for m, dur in seq:
        if m is not None:
            put(pat, row, ch, note=N(m+transpose), ins=ins, vol=vol)
            end = row + dur*4
            if dur < 4: keyoff(pat, end-1, ch)
        row += dur*4
    return row

def drums(pat, style, fills=0):
    K, S, H = KICK, SNR, HAT
    if style == 'none': return
    if style == 'int':
        for r in (0,8): put(pat, r, K, note=73, ins=9, vol=64)
        for r in (4,12): put(pat, r, H, note=73, ins=11, vol=44)
        return
    if style == 'main':
        for r in (0,6,8,14): put(pat, r, K, note=73, ins=9, vol=64)
        for r in (4,12): put(pat, r, S, note=73, ins=10, vol=58)
        for r in range(0,16,2): put(pat, r, H, note=73, ins=11, vol=40 if r%4==0 else 30)
        for r in (3,11): put(pat, r, H, note=74, ins=12, vol=38)
        return
    if style == 'drive':
        for r in (0,3,8,11): put(pat, r, K, note=73, ins=9, vol=64)
        for r in (4,12): put(pat, r, S, note=73, ins=10, vol=60)
        for r in (6,14): put(pat, r, S, note=73, ins=13, vol=44)
        for r in range(16): put(pat, r, H, note=73, ins=11, vol=38 if r%2==0 else 26)
        return
    if style == 'break':
        for r in (0,8): put(pat, r, K, note=73, ins=9, vol=60)
        for r in (4,12): put(pat, r, S, note=73, ins=10, vol=56)
        for r in (0,3,6,9,12,15): put(pat, r, TOM, note=61+r, ins=14, vol=48)
        for r in range(0,16,4): put(pat, r, H, note=73, ins=11, vol=34)
        return
    if style == 'fill':
        for i in range(16):
            put(pat, i, TOM if i < 12 else TOMH, note=57+int(i*0.9), ins=14 if i < 12 else 15,
                vol=40+int(i*1.4))
            put(pat, i, S, note=73, ins=10, vol=54) if i % 4 == 3 else None
        put(pat, 15, K, note=73, ins=9, vol=64)
        return

# ---------------- song sections ----------------
def make_pattern(kind, chord, opts=None):
    p = new_pattern()
    o = opts or {}
    # panning on every channel
    for ch, pan in PANCH.items():
        put(p, 0, ch, fx=8, fxp=pan)
    if kind in ('silent',):
        return p
    if o.get('drums'): drums(p, o['drums'], o.get('fill',0))
    if o.get('bass'): bass_seq(p, chord, o['bass'], vol=o.get('bassvol',60))
    if o.get('sub'): sub_seq(p, chord, vol=o.get('subvol',42))
    if o.get('pad'): pad_chord(p, chord, o.get('padocts',(1,2)), o.get('padvols',(38,34)))
    if o.get('arp'): arp_fig(p, chord, o['arp'], vol=o.get('arpvol',40))
    if o.get('plock'): plock_seq(p, chord, o['plock'], vol=o.get('plcvol',40), ch=PLC)
    if o.get('plock2'): plock_seq(p, chord, o['plock2'], vol=o.get('plc2vol',34), ch=PLC2)
    if o.get('organ'): organ_stab(p, chord, rows=o.get('organrows',(6,14)), vol=o.get('orgvol',38))
    if o.get('mel'): melody_seq(p, o['mel'], ch=o.get('melch',LD), vol=o.get('melvol',62))
    if o.get('mel2'): melody_seq(p, o['mel2'], ch=LD2, vol=o.get('mel2vol',46), transpose=o.get('mel2tr',3))
    if o.get('fxrow') is not None:
        put(p, o['fxrow'], FX, note=73, ins=o.get('fxins',17), vol=o.get('fxvol',44))
    if o.get('crash'): put(p, 0, FX, note=85, ins=16, vol=o.get('crashvol',44))
    return p
PYEOF
echo written"}

